--- clean/crates/crypto/circuits/src/transfer/inspection.rs
+++ overlay/crates/crypto/circuits/src/transfer/inspection.rs
@@ -0,0 +1,295 @@
+//! Bounded read-only caller and spend-authorization role capture.
+use super::*;
+use crate::scalar::inspection::Observed;
+use commonware_cryptography::zk::circuit::CircuitIdx;
+use std::{cell::RefCell, marker::PhantomData, rc::Rc};
+
+#[derive(Clone, PartialEq, Eq)]
+pub struct Caller {
+    pub regulated: Observed,
+    pub asset: Observed,
+    pub leaf_ring: [Observed; 2],
+    pub fixed_ring: [Observed; 2],
+    pub selected_ring: [Observed; 2],
+    pub address: [Observed; 4],
+    pub rnk_dh: [Observed; 2],
+    pub registered_rnk: Observed,
+    pub ak: [Observed; 2],
+    pub nk: Observed,
+    pub effective_nk: Observed,
+}
+#[derive(Clone, PartialEq, Eq)]
+pub struct Spend {
+    pub ak: [Observed; 2],
+    pub randomizer: Observed,
+    pub bits: Vec<CircuitIdx>,
+    pub generator: [Observed; 2],
+    pub contribution: [Observed; 2],
+    pub computed: [Observed; 2],
+    pub rk: [Observed; 2],
+}
+#[derive(Clone, PartialEq, Eq)]
+pub struct Report {
+    pub caller: Caller,
+    pub spend: Spend,
+}
+#[derive(Default)]
+struct State {
+    caller: Option<Caller>,
+    spend: Option<Spend>,
+    overflow: bool,
+    taken: bool,
+}
+thread_local! { static STATE: RefCell<Option<State>> = const { RefCell::new(None) }; }
+pub struct Capture {
+    _thread: PhantomData<Rc<()>>,
+}
+impl Drop for Capture {
+    fn drop(&mut self) {
+        STATE.with(|s| *s.borrow_mut() = None);
+    }
+}
+pub fn begin() -> Result<Capture> {
+    STATE.with(|state| {
+        let mut state = state.borrow_mut();
+        ensure!(state.is_none(), "nested transfer role capture");
+        *state = Some(State::default());
+        Ok(Capture {
+            _thread: PhantomData,
+        })
+    })
+}
+fn observed(value: &Var<'_, Scalar>) -> Observed {
+    match value.inspect_circuit_idx() {
+        Some(index) => Observed::Source(index),
+        None => Observed::Native(
+            value
+                .inspect_native()
+                .expect("invalid role variable")
+                .clone(),
+        ),
+    }
+}
+fn point(value: &Point<Var<'_, Scalar>>) -> [Observed; 2] {
+    [observed(&value.x), observed(&value.y)]
+}
+fn native(value: &Point<Scalar>) -> [Observed; 2] {
+    [
+        Observed::Native(value.x.clone()),
+        Observed::Native(value.y.clone()),
+    ]
+}
+pub(super) fn caller(
+    regulated: &BoolVar<'_, Scalar>,
+    asset: &Var<'_, Scalar>,
+    leaf_ring: &Point<Var<'_, Scalar>>,
+    fixed_ring: &Point<Scalar>,
+    selected_ring: &Point<Var<'_, Scalar>>,
+    address: &Address<Var<'_, Scalar>>,
+    rnk_dh: &Point<Var<'_, Scalar>>,
+    registered: &Var<'_, Scalar>,
+    auth: &authorization::Output<'_>,
+) {
+    STATE.with(|state| {
+        let mut state = state.borrow_mut();
+        let Some(state) = state.as_mut() else {
+            return;
+        };
+        if state.caller.is_some() || state.spend.is_some() || state.taken {
+            state.overflow = true;
+            return;
+        }
+        state.caller = Some(Caller {
+            regulated: observed(regulated.var()),
+            asset: observed(asset),
+            leaf_ring: point(leaf_ring),
+            fixed_ring: native(fixed_ring),
+            selected_ring: point(selected_ring),
+            address: [
+                observed(&address.diversified.x),
+                observed(&address.diversified.y),
+                observed(&address.transmission.x),
+                observed(&address.transmission.y),
+            ],
+            rnk_dh: point(rnk_dh),
+            registered_rnk: observed(registered),
+            ak: point(&auth.ak),
+            nk: observed(&auth.nk),
+            effective_nk: observed(&auth.effective_nk),
+        });
+    });
+}
+pub(crate) fn spend(
+    ak: &Point<Var<'_, Scalar>>,
+    randomizer: &Var<'_, Scalar>,
+    bits: &[BoolVar<'_, Scalar>],
+    generator: &Point<Scalar>,
+    contribution: &Point<Var<'_, Scalar>>,
+    computed: &Point<Var<'_, Scalar>>,
+    rk: &Point<Var<'_, Scalar>>,
+) {
+    STATE.with(|state| {
+        let mut state = state.borrow_mut();
+        let Some(state) = state.as_mut() else {
+            return;
+        };
+        if state.caller.is_none() || state.spend.is_some() || state.taken || bits.len() != 252 {
+            state.overflow = true;
+            return;
+        }
+        let handles: Option<Vec<_>> = bits
+            .iter()
+            .map(|bit| bit.var().inspect_circuit_idx())
+            .collect();
+        let Some(bits) = handles else {
+            state.overflow = true;
+            return;
+        };
+        state.spend = Some(Spend {
+            ak: point(ak),
+            randomizer: observed(randomizer),
+            bits,
+            generator: native(generator),
+            contribution: point(contribution),
+            computed: point(computed),
+            rk: point(rk),
+        });
+    });
+}
+pub fn take() -> Result<Report> {
+    STATE.with(|state| {
+        let mut state = state.borrow_mut();
+        let state = state
+            .as_mut()
+            .ok_or_else(|| anyhow::anyhow!("inactive transfer role capture"))?;
+        ensure!(
+            !state.overflow && !state.taken,
+            "invalid/repeated transfer role capture"
+        );
+        let caller = state
+            .caller
+            .clone()
+            .ok_or_else(|| anyhow::anyhow!("missing transfer caller roles"))?;
+        let spend = state
+            .spend
+            .clone()
+            .ok_or_else(|| anyhow::anyhow!("missing spend authorization roles"))?;
+        ensure!(caller.ak == spend.ak, "transfer/spend AK role mismatch");
+        state.taken = true;
+        Ok(Report { caller, spend })
+    })
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+    #[test]
+    fn roles_capture_is_exclusive_and_cleans_up_on_error_and_panic() {
+        {
+            let _capture = begin().unwrap();
+            assert!(begin().is_err());
+            assert!(take().is_err());
+        }
+        assert!(take().is_err());
+        assert!(std::panic::catch_unwind(|| {
+            let _capture = begin().unwrap();
+            panic!("synthetic role failure");
+        })
+        .is_err());
+        {
+            let _capture = begin().unwrap();
+            assert!(take().is_err());
+        }
+        assert!(take().is_err());
+    }
+    #[test]
+    fn roles_capture_rejects_order_duplicates_bits_and_ak_mismatch() {
+        use commonware_cryptography::zk::circuit;
+        for case in 0..7 {
+            let _capture = begin().unwrap();
+            let _ = circuit::build(|ctx| {
+                let p = Point {
+                    x: Var::zero(),
+                    y: Var::native(Scalar::one()),
+                };
+                let fixed = Point {
+                    x: Scalar::zero(),
+                    y: Scalar::one(),
+                };
+                let address = Address {
+                    diversified: p.clone(),
+                    transmission: p.clone(),
+                };
+                let auth = authorization::Output {
+                    ak: p.clone(),
+                    nk: Var::zero(),
+                    effective_nk: Var::zero(),
+                };
+                let bits: Vec<_> = (0..252).map(|_| BoolVar::witness(ctx, |_| false)).collect();
+                let record_caller = || {
+                    caller(
+                        &BoolVar::constant(false),
+                        &Var::zero(),
+                        &p,
+                        &fixed,
+                        &p,
+                        &address,
+                        &p,
+                        &Var::zero(),
+                        &auth,
+                    )
+                };
+                let record_spend = |bits: &[BoolVar<'_, Scalar>]| {
+                    spend(&p, &Var::zero(), bits, &fixed, &p, &p, &p)
+                };
+                if case == 1 {
+                    record_spend(&bits);
+                }
+                record_caller();
+                if case == 2 {
+                    record_caller();
+                }
+                if case == 4 {
+                    record_spend(&bits[..251]);
+                } else if case == 5 {
+                    record_spend(&vec![BoolVar::constant(false); 252]);
+                } else {
+                    record_spend(&bits);
+                }
+                if case == 3 {
+                    record_spend(&bits);
+                }
+                if case == 6 {
+                    STATE.with(|state| {
+                        state
+                            .borrow_mut()
+                            .as_mut()
+                            .unwrap()
+                            .caller
+                            .as_mut()
+                            .unwrap()
+                            .ak[0] = Observed::Native(Scalar::one())
+                    });
+                }
+                if case == 0 {
+                    take().unwrap();
+                    assert_eq!(
+                        take().err().unwrap().to_string(),
+                        "invalid/repeated transfer role capture"
+                    );
+                } else if case == 6 {
+                    assert_eq!(
+                        take().err().unwrap().to_string(),
+                        "transfer/spend AK role mismatch"
+                    );
+                } else {
+                    assert_eq!(
+                        take().err().unwrap().to_string(),
+                        "invalid/repeated transfer role capture"
+                    );
+                }
+                Vec::<Var<'_, Scalar>>::new()
+            });
+        }
+    }
+}
